A few things to know:

- I also made `get` raise `KeyError` for a missing key in every backend. The protocol only checks signatures, so behaviour like this is a convention you have to keep yourself. Put it in the protocol's docstring.
- `@runtime_checkable` only exists so `isinstance(x, BlobStore)` works. At runtime that check only looks at whether the method names exist, not at the signatures. You don't need it for static checking.
- If you have `boto3-stubs[s3]` installed, replace `client: Any` with `S3Client` from `mypy_boto3_s3` and mypy will check the boto3 calls too.

```python
from collections import OrderedDict
from collections.abc import Hashable, Iterator
from typing import overload


class LRUCache[K: Hashable, V]:
    def __init__(self, maxsize: int = 128) -> None:
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")
        self.maxsize = maxsize
        self._data: OrderedDict[K, V] = OrderedDict()
        self.hits = 0
        self.misses = 0

    @overload
    def get(self, key: K) -> V | None: ...
    @overload
    def get[D](self, key: K, default: D) -> V | D: ...
    def get(self, key, default=None):
        try:
            value = self._data[key]
        except KeyError:
            self.misses += 1
            return default
        self._data.move_to_end(key)
        self.hits += 1
        return value

    def put(self, key: K, value: V) -> None:
        self._data[key] = value
        self._data.move_to_end(key)
        if len(self._data) > self.maxsize:
            self._data.popitem(last=False)  # evict least recently used

    def __contains__(self, key: object) -> bool:
        return key in self._data  # doesn't count as a hit and doesn't touch the order

    def __len__(self) -> int:
        return len(self._data)

    def __iter__(self) -> Iterator[K]:
        return iter(self._data)

    def clear(self) -> None:
        self._data.clear()
        self.hits = self.misses = 0
```

```python
cache: LRUCache[str, bytes] = LRUCache(maxsize=2)
cache.put("a", b"1")
cache.put("b", b"2")
cache.get("a")          # bytes | None, "a" is now most recent
cache.put("c", b"3")    # evicts "b"
print(list(cache))      # ['a', 'c']
cache.put("x", 42)      # mypy: Argument 2 to "put" of "LRUCache" has incompatible type "int"; expected "bytes"
```

The two `get` overloads let the type checker narrow the result: `cache.get(k)` is `bytes | None`, but `cache.get(k, b"")` is just `bytes`.

