```python
# perf.py
from __future__ import annotations

import functools
import logging
import time
from collections.abc import Callable
from typing import ParamSpec, TypeVar, overload

P = ParamSpec("P")
R = TypeVar("R")

_default_logger = logging.getLogger("perf")


@overload
def log_slow(func: Callable[P, R], /) -> Callable[P, R]: ...
@overload
def log_slow(
    *, threshold: float = 1.0, logger: logging.Logger | None = None
) -> Callable[[Callable[P, R]], Callable[P, R]]: ...
def log_slow(
    func: Callable[P, R] | None = None,
    /,
    *,
    threshold: float = 1.0,
    logger: logging.Logger | None = None,
) -> Callable[P, R] | Callable[[Callable[P, R]], Callable[P, R]]:
    """Log a warning when the decorated function runs longer than `threshold` seconds."""
    log = logger or _default_logger

    def decorator(fn: Callable[P, R]) -> Callable[P, R]:
        @functools.wraps(fn)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            start = time.perf_counter()
            try:
                return fn(*args, **kwargs)
            finally:
                elapsed = time.perf_counter() - start
                if elapsed >= threshold:
                    log.warning("%s took %.3fs (threshold %.3fs)",
                                fn.__qualname__, elapsed, threshold)

        return wrapper

    if func is not None:      # used as @log_slow
        return decorator(func)
    return decorator          # used as @log_slow(...)
```

```python
import inspect
import logging

from perf import log_slow

logging.basicConfig(level=logging.INFO)


@log_slow
def load_catalog(path: str, *, strict: bool = False) -> list[dict[str, str]]:
    """Load the product catalog from a CSV file."""
    ...


@log_slow(threshold=0.05, logger=logging.getLogger("scoring"))
def score(values: list[float]) -> float:
    return sum(values) / len(values)


print(inspect.signature(load_catalog))  # (path: str, *, strict: bool = False) -> list[dict[str, str]]
print(load_catalog.__name__)            # load_catalog
print(load_catalog.__doc__)             # Load the product catalog from a CSV file.
```

How it works:

- When used without parentheses, Python calls `log_slow(load_catalog)`, so `func` is set. With parentheses, `func` is `None` and you get the real decorator back.
- `/` makes `func` positional-only and `*` makes the options keyword-only. That's what keeps the two forms unambiguous: `@log_slow(0.2)` is a `TypeError` instead of silently treating `0.2` as the function.
- `functools.wraps` copies `__name__`, `__doc__`, `__module__`, `__qualname__` and sets `__wrapped__`. `inspect.signature` follows `__wrapped__`, which is why it shows the original parameters. The overloads plus `ParamSpec` do the same for mypy/pyright.
- The check is in `finally`, so slow calls that raise get logged too.

This version is sync only. If you also decorate `async def` functions, branch on `inspect.iscoroutinefunction(fn)` and use an `async def wrapper` that awaits `fn`. Otherwise you'd only time how long it takes to *create* the coroutine, which is roughly zero.

