subprocess.run([...], env=env, check=True)
```

If you also need a temporary working directory, `contextlib.chdir` (3.11+) does that, and both fit in one `with` statement.

Turn the parsing into a generator and make `LogReader` iterable. Then nothing is held in memory except the entry being built. `read()` stays for old callers, and entries still unpack like the old tuples.

```python
# logreader.py
from __future__ import annotations

from collections.abc import Iterable, Iterator
from dataclasses import dataclass, field
from pathlib import Path


@dataclass(slots=True)
class LogEntry:
    timestamp: str
    level: str
    message: str
    continuation: list[str] = field(default_factory=list)

    @property
    def full_message(self) -> str:
        return "\n".join([self.message, *self.continuation])

    def __iter__(self) -> Iterator[str]:
        # keeps old call sites like `ts, level, msg = entry` working
        return iter((self.timestamp, self.level, self.message))


def parse_entries(lines: Iterable[str]) -> Iterator[LogEntry]:
    """Group raw lines into entries. Lines starting with whitespace belong to the previous entry."""
    current: LogEntry | None = None
    for raw in lines:
        line = raw.rstrip("\r\n")
        if not line.strip() or line.startswith("#"):
            continue
        if line[0].isspace():
            if current is not None:
                current.continuation.append(line.rstrip())
            continue
        parts = line.split(" ", 2)
        if len(parts) < 3:
            # malformed header line: keep it with the previous entry instead of crashing
            if current is not None:
                current.continuation.append(line)
            continue
        if current is not None:
            yield current
        current = LogEntry(parts[0], parts[1], parts[2])
    if current is not None:
        yield current


class LogReader:
    def __init__(self, path: str | Path, *, encoding: str = "utf-8") -> None:
        self.path = Path(path)
        self.encoding = encoding

    def __iter__(self) -> Iterator[LogEntry]:
        with self.path.open(encoding=self.encoding, errors="replace") as f:
            yield from parse_entries(f)

    def filter(self, *levels: str) -> Iterator[LogEntry]:
        wanted = {level.upper() for level in levels}
        return (entry for entry in self if entry.level in wanted)

    def read(self) -> list[LogEntry]:
        """Old API. Loads the whole file; prefer iterating."""
        return list(self)
```

Usage:

```python
from collections import Counter
from itertools import islice

reader = LogReader("/var/log/shop/app.log")

for entry in reader.filter("ERROR", "CRITICAL"):
    print(entry.timestamp, entry.full_message)

levels = Counter(entry.level for entry in reader)   # constant memory, one pass
first_100 = list(islice(reader, 100))               # stops reading after 100 entries

for ts, level, msg in reader.read():                # old code still works (on small files)
    ...
```

A few notes:

- Each `for` over `reader` opens the file again, so you can iterate it several times. That's different from a one-shot generator.
- The continuation handling has to look one line ahead: an entry is only complete when the next header line arrives. That's why `current` is yielded when the *next* entry starts, and once more at the end of the file.
- `parse_entries` takes any iterable of strings, so you can test it with a list and no files:

  ```python
  lines = ["2025-01-14T08:03:11Z ERROR boom\n", "  File \"x.py\", line 3\n", "2025-01-14T08:03:12Z INFO ok\n"]
  entries = list(parse_entries(lines))
  assert entries[0].continuation == ['  File "x.py", line 3']
  ```
- `errors="replace"` stops one bad byte in an 8 GB file from killing the whole run with `UnicodeDecodeError`.
- If a consumer stops early (`break`), the file is closed when the generator is garbage collected, which in CPython happens right away. Wrap it in `contextlib.closing(iter(reader))` if you need that guaranteed on other interpreters.

Both are doable. First a small vector class with operators. `__slots__` drops the per-instance `__dict__`, which matters a lot when you have millions of small objects.

```python
# vec.py
from __future__ import annotations

import math
from collections.abc import Iterator


class Vec2:
    __slots__ = ("x", "y")

    def __init__(self, x: float = 0.0, y: float = 0.0) -> None:
        self.x = float(x)
        self.y = float(y)

    def __repr__(self) -> str:
        return f"Vec2({self.x!r}, {self.y!r})"

    def __iter__(self) -> Iterator[float]:  # allows x, y = v
        yield self.x
        yield self.y

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Vec2):
            return NotImplemented
        return self.x == other.x and self.y == other.y
    # defining __eq__ sets __hash__ to None: Vec2 is mutable, so it must not be hashable

    def __bool__(self) -> bool:
        return self.x != 0.0 or self.y != 0.0

    def __add__(self, other: Vec2) -> Vec2:
        if not isinstance(other, Vec2):
            return NotImplemented
        return Vec2(self.x + other.x, self.y + other.y)

    def __sub__(self, other: Vec2) -> Vec2:
        if not isinstance(other, Vec2):
            return NotImplemented
        return Vec2(self.x - other.x, self.y - other.y)

    def __mul__(self, k: float) -> Vec2:
        if not isinstance(k, (int, float)):
            return NotImplemented
        return Vec2(self.x * k, self.y * k)

    __rmul__ = __mul__  # so 0.5 * v works as well as v * 0.5

    def __truediv__(self, k: float) -> Vec2:
        if not isinstance(k, (int, float)):
            return NotImplemented
        return Vec2(self.x / k, self.y / k)

    def __neg__(self) -> Vec2:
        return Vec2(-self.x, -self.y)

    def __abs__(self) -> float:
        return math.hypot(self.x, self.y)

    # in-place operators mutate instead of allocating a new Vec2
    def __iadd__(self, other: Vec2) -> Vec2:
        if not isinstance(other, Vec2):
            return NotImplemented
        self.x += other.x
        self.y += other.y
        return self

    def __imul__(self, k: float) -> Vec2:
        if not isinstance(k, (int, float)):
            return NotImplemented
        self.x *= k
        self.y *= k
        return self

    def dot(self, other: Vec2) -> float:
        return self.x * other.x + self.y * other.y

    def normalized(self) -> Vec2:
        length = abs(self)
        if length == 0.0:
            raise ZeroDivisionError("cannot normalize a zero vector")
        return self / length


class Particle:
    __slots__ = ("pos", "vel")

    def __init__(self, pos: Vec2, vel: Vec2) -> None:
        self.pos = pos
        self.vel = vel

    def step(self, dt: float, accel: Vec2) -> None:
        self.vel += accel * dt
        self.pos += self.vel * dt
```

```python
gravity = Vec2(0, -9.81)
particles = [Particle(Vec2(i % 1000, 50), Vec2(1, 0)) for i in range(10)]
for p in particles:
    p.step(0.016, gravity)
print(particles[0].pos)   # Vec2(0.016, 49.99748864)
```

Watch out for one thing: `+=` mutates the vector in place. If several particles share one `Vec2` object, e.g. `start = Vec2(0, 0)` followed by `Particle(start, ...)` in a loop, they all move together. Give each particle its own vectors (`Vec2(*start)`).

To check the memory effect on your machine instead of trusting anyone's numbers:

```python
import tracemalloc


class PlainParticle:
    def __init__(self, x, y, vx, vy):
        self.x, self.y, self.vx, self.vy = x, y, vx, vy


class SlotParticle:
    __slots__ = ("x", "y", "vx", "vy")

    def __init__(self, x, y, vx, vy):
        self.x, self.y, self.vx, self.vy = x, y, vx, vy


def bytes_per_object(cls, n=200_000):
    tracemalloc.start()
    objs = [cls(float(i), 0.5, 1.0, -1.0) for i in range(n)]
    current, _ = tracemalloc.get_traced_memory()
    tracemalloc.stop()
    del objs
    return current / n


for cls in (PlainParticle, SlotParticle):
    print(f"{cls.__name__:15} {bytes_per_object(cls):6.0f} bytes/particle")
```

The honest answer for 5 million particles, though: any per-particle Python object is the bottleneck, for memory *and* speed. `Particle` + two `Vec2` objects is 3 objects per particle, and `p.vel * dt` creates a temporary object on every step. With NumPy you store all particles as a few big arrays and update them in one operation:

```python
import numpy as np

n = 5_000_000
rng = np.random.default_rng(42)
pos = rng.uniform(0.0, 100.0, size=(n, 2))   # float64: 5M x 2 x 8 bytes = 80 MB
vel = np.zeros((n, 2))                       # another 80 MB
gravity = np.array([0.0, -9.81])


def step(pos: np.ndarray, vel: np.ndarray, dt: float) -> None:
    vel += gravity * dt   # in place, whole array at once
    pos += vel * dt
```

So: keep `Vec2` for game logic, tools and anything with hundreds or thousands of objects. For the 5M-particle core loop, use arrays.

```python
# money.py
from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from functools import total_ordering

# ISO 4217 minor units for currencies that don't use 2 decimals
_MINOR_UNITS = {"JPY": 0, "KRW": 0, "ISK": 0, "BHD": 3, "KWD": 3}


def _unit(currency: str) -> Decimal:
    return Decimal(1).scaleb(-_MINOR_UNITS.get(currency, 2))  # EUR -> 0.01, JPY -> 1


class CurrencyMismatch(ValueError):
    pass


@total_ordering
@dataclass(frozen=True, slots=True)
class Money:
    amount: Decimal
    currency: str

    def __post_init__(self) -> None:
        if isinstance(self.amount, float):
            raise TypeError("use str, int or Decimal for money, never float")
        currency = self.currency.upper()
        if len(currency) != 3 or not currency.isalpha():
            raise ValueError(f"invalid currency code: {self.currency!r}")
        amount = Decimal(self.amount).quantize(_unit(currency), rounding=ROUND_HALF_UP)
        # frozen dataclass: normalising in __post_init__ needs object.__setattr__
        object.__setattr__(self, "currency", currency)
        object.__setattr__(self, "amount", amount)

    @classmethod
    def of(cls, amount: str | int | Decimal, currency: str) -> Money:
        return cls(Decimal(amount), currency)

    @classmethod
    def zero(cls, currency: str) -> Money:
        return cls(Decimal(0), currency)

    def _check_currency(self, other: Money) -> None:
        if other.currency != self.currency:
            raise CurrencyMismatch(f"cannot combine {self.currency} and {other.currency}")

    def __add__(self, other: Money) -> Money:
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money(self.amount + other.amount, self.currency)

    def __radd__(self, other: object) -> Money:
        if other == 0:  # makes sum(list_of_money) work, sum() starts with 0
            return self
        return NotImplemented

    def __sub__(self, other: Money) -> Money:
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money(self.amount - other.amount, self.currency)

    def __mul__(self, factor: int | Decimal) -> Money:
        if isinstance(factor, bool) or not isinstance(factor, (int, Decimal)):
            return NotImplemented
        return Money(self.amount * factor, self.currency)

    __rmul__ = __mul__

    def __neg__(self) -> Money:
        return Money(-self.amount, self.currency)

    def __abs__(self) -> Money:
        return Money(abs(self.amount), self.currency)

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self.amount < other.amount

    def __str__(self) -> str:
        return f"{self.amount:,} {self.currency}"
```

```python
price = Money.of("19.99", "EUR")
vat = price * Decimal("0.19")           # 3.7981 -> rounded half-up
print(vat)                              # 3.80 EUR
print(Money.of("2.345", "EUR"))         # 2.35 EUR (banker's rounding would give 2.34)
print(sum([price, vat, Money.of("5", "EUR")]))   # 28.79 EUR
print(Money.of("1500", "JPY") * 3)      # 4,500 JPY
print(price > Money.of("10", "EUR"))    # True

price + Money.of("5", "USD")   # CurrencyMismatch: cannot combine EUR and USD
price * 1.1                    # TypeError: unsupported operand type(s) for *: 'Money' and 'float'
```

Design decisions:

- **Rounding happens in exactly one place**, `__post_init__`, so every `Money` that exists is already rounded to its currency's minor unit. Every result of `+`, `-` and `*` goes through it too.
- **Floats are rejected** on purpose: `Decimal(0.1)` is `0.1000000000000000055511151231257827...`. If a factor comes in as a float, convert it with `Decimal(str(x))` at the edge of your system.
- `frozen=True` makes instances immutable and hashable (usable as dict keys). `==` compares amount *and* currency, so `5 EUR != 5 USD`. `<` raises on a currency mismatch instead of returning a meaningless answer.
- `Money.of(...)` exists so call sites can pass strings while the `amount` attribute stays typed as `Decimal`.

