What keeps it fast with 40k books:

- **The book list runs a fixed number of queries,** no matter how many rows: one for the page with the loan count annotated, one prefetch for the authors, and the paginator count. Without the prefetch you'd get one extra query per row for `author_names`.
- **`distinct=True` in the `Count` is required, not optional.** When you search by author name, Django joins the authors table. Without `distinct`, a book with two authors would report twice as many loans.
- `=isbn` makes the ISBN search an exact match instead of `LIKE '%...%'`, so the unique index can be used.
- `autocomplete_fields` replace `<select>` boxes that would otherwise render all 40k books (on the loan form) or all authors (on the book form).
- The bulk action uses a single `UPDATE`. It skips loans that were already returned, so their original return date isn't overwritten.

If the list still feels slow, enable `django-debug-toolbar` or log `connection.queries` and look for the `LIKE '%term%'` on `title`. A plain B-tree index can't serve a leading-wildcard search. On PostgreSQL a trigram index (`pg_trgm` with `GinIndex(..., opclasses=["gin_trgm_ops"])`) fixes that.

Qt has no flow layout built in, so the code has three parts: a small `FlowLayout` that wraps, a `Chip` widget, and the `TagInput` that ties them together.

```python
# tag_input.py
from __future__ import annotations

import sys
from collections.abc import Iterable

from PySide6.QtCore import QEvent, QObject, QPoint, QRect, QSize, Qt, Signal
from PySide6.QtGui import QKeyEvent, QMouseEvent
from PySide6.QtWidgets import (
    QApplication,
    QFrame,
    QHBoxLayout,
    QLabel,
    QLayout,
    QLayoutItem,
    QLineEdit,
    QToolButton,
    QWidget,
    QWidgetItem,
)


class FlowLayout(QLayout):
    """Places items left to right and wraps to a new line when the width runs out."""

    def __init__(self, parent: QWidget | None = None, spacing: int = 6) -> None:
        super().__init__(parent)
        self._items: list[QLayoutItem] = []
        self._spacing = spacing

    def addItem(self, item: QLayoutItem) -> None:
        self._items.append(item)

    def insertWidget(self, index: int, widget: QWidget) -> None:
        self.addChildWidget(widget)
        self._items.insert(index, QWidgetItem(widget))
        self.invalidate()

    def takeWidget(self, widget: QWidget) -> None:
        for i, item in enumerate(self._items):
            if item.widget() is widget:
                del self._items[i]
                self.invalidate()
                return

    def count(self) -> int:
        return len(self._items)

    def itemAt(self, index: int) -> QLayoutItem | None:
        return self._items[index] if 0 <= index < len(self._items) else None

    def takeAt(self, index: int) -> QLayoutItem | None:
        return self._items.pop(index) if 0 <= index < len(self._items) else None

    def hasHeightForWidth(self) -> bool:
        return True

    def heightForWidth(self, width: int) -> int:
        return self._arrange(QRect(0, 0, width, 0), apply=False)

    def setGeometry(self, rect: QRect) -> None:
        super().setGeometry(rect)
        self._arrange(rect, apply=True)

    def sizeHint(self) -> QSize:
        return self.minimumSize()

    def minimumSize(self) -> QSize:
        size = QSize()
        for item in self._items:
            size = size.expandedTo(item.minimumSize())
        m = self.contentsMargins()
        return size + QSize(m.left() + m.right(), m.top() + m.bottom())

    def _arrange(self, rect: QRect, *, apply: bool) -> int:
        m = self.contentsMargins()
        area = rect.adjusted(m.left(), m.top(), -m.right(), -m.bottom())
        x, y, line_height = area.x(), area.y(), 0
        for item in self._items:
            hint = item.sizeHint()
            if x + hint.width() > area.right() + 1 and line_height > 0:
                x, y = area.x(), y + line_height + self._spacing
                line_height = 0
            if apply:
                item.setGeometry(QRect(QPoint(x, y), hint))
            x += hint.width() + self._spacing
            line_height = max(line_height, hint.height())
        return y + line_height - rect.y() + m.bottom()


class Chip(QFrame):
    removeRequested = Signal(str)

    def __init__(self, text: str, parent: QWidget | None = None) -> None:
        super().__init__(parent)
        self.text = text
        self.setObjectName("chip")
        layout = QHBoxLayout(self)
        layout.setContentsMargins(8, 1, 2, 1)
        layout.setSpacing(2)
        layout.addWidget(QLabel(text))
        close = QToolButton(self)
        close.setText("×")
        close.setAutoRaise(True)
        close.setCursor(Qt.CursorShape.PointingHandCursor)
        close.setToolTip(f"Remove {text}")
        close.clicked.connect(lambda: self.removeRequested.emit(self.text))
        layout.addWidget(close)


class TagInput(QFrame):
    tagsChanged = Signal(list)

    def __init__(self, parent: QWidget | None = None, *, placeholder: str = "Add tag…",
                 case_sensitive: bool = False) -> None:
        super().__init__(parent)
        self.setFrameShape(QFrame.Shape.StyledPanel)
        self.setStyleSheet("""
            #chip { background: #e8eefc; border: 1px solid #b5c7f2; border-radius: 10px; }
            #chip QToolButton { border: none; padding: 0 3px; }
        """)
        self._case_sensitive = case_sensitive
        self._chips: list[Chip] = []

        self._flow = FlowLayout(self)
        self._flow.setContentsMargins(4, 4, 4, 4)
        self._edit = QLineEdit(self)
        self._edit.setFrame(False)
        self._edit.setPlaceholderText(placeholder)
        self._edit.setMinimumWidth(120)
        self._edit.returnPressed.connect(self._commit_text)
        self._edit.installEventFilter(self)
        self._flow.addWidget(self._edit)
        self.setFocusProxy(self._edit)

    # public API -----------------------------------------------------------
    def tags(self) -> list[str]:
        return [chip.text for chip in self._chips]

    def setTags(self, tags: Iterable[str]) -> None:
        for chip in list(self._chips):
            self._remove_chip(chip)
        for tag in tags:
            self._add_chip(tag)
        self.tagsChanged.emit(self.tags())

    def addTag(self, text: str) -> bool:
        added = self._add_chip(text)
        if added:
            self.tagsChanged.emit(self.tags())
        return added

    def removeTag(self, text: str) -> None:
        for chip in self._chips:
            if chip.text == text:
                self._remove_chip(chip)
                self.tagsChanged.emit(self.tags())
                return

    # internals -------------------------------------------------------------
    def _key(self, text: str) -> str:
        return text if self._case_sensitive else text.casefold()

    def _add_chip(self, text: str) -> bool:
        text = text.strip()
        if not text or any(self._key(c.text) == self._key(text) for c in self._chips):
            return False
        chip = Chip(text, self)
        chip.removeRequested.connect(self.removeTag)
        self._flow.insertWidget(len(self._chips), chip)  # chips go before the line edit
        self._chips.append(chip)
        return True

    def _remove_chip(self, chip: Chip) -> None:
        self._chips.remove(chip)
        self._flow.takeWidget(chip)
        chip.deleteLater()

    def _commit_text(self) -> None:
        added = [part for part in self._edit.text().split(",") if self._add_chip(part)]
        self._edit.clear()
        if added:
            self.tagsChanged.emit(self.tags())

    def eventFilter(self, obj: QObject, event: QEvent) -> bool:
        if obj is self._edit and isinstance(event, QKeyEvent) and event.type() == QEvent.Type.KeyPress:
            if event.key() == Qt.Key.Key_Comma:
                self._commit_text()
                return True
            if event.key() == Qt.Key.Key_Backspace and not self._edit.text() and self._chips:
                self.removeTag(self._chips[-1].text)
                return True
        return super().eventFilter(obj, event)

    def mousePressEvent(self, event: QMouseEvent) -> None:
        self._edit.setFocus()  # clicking anywhere in the box focuses the input
        super().mousePressEvent(event)


if __name__ == "__main__":
    app = QApplication(sys.argv)
    widget = TagInput()
    widget.setTags(["python", "qt", "gui"])
    widget.tagsChanged.connect(lambda tags: print("tags:", tags))
    widget.resize(380, 90)
    widget.show()
    sys.exit(app.exec())
```

Design notes:

- **Removal goes through `takeWidget`**, not `QLayout.removeWidget`. `removeWidget` would ask Qt to `delete` the layout item that Python created, and ownership across the C++/Python boundary is where PySide crashes come from. This way Python owns the item and Qt deletes only the widget (`deleteLater`).
- **`hasHeightForWidth`/`heightForWidth`** are what let the widget grow taller when the chips wrap. Without them, the parent layout gives it one line of height and the extra chips get cut off.
- **`setTags` emits once**, not once per tag, so a slot connected to `tagsChanged` doesn't run 20 times when you load a record.
- Duplicates are ignored case-insensitively by default (`Python` = `python`). Pass `case_sensitive=True` if that's wrong for your data.
- The signal is `Signal(list)`, so the slot receives a plain Python `list[str]`.

