#!/usr/bin/env python3
# notes.py
from __future__ import annotations

import cmd
import json
import re
import sys
from collections import Counter
from dataclasses import asdict, dataclass, field
from datetime import datetime
from pathlib import Path

TAG_RE = re.compile(r"#([\w-]+)")
DEFAULT_FILE = Path.home() / ".notes.json"


@dataclass
class Note:
    id: int
    text: str
    created: str = field(default_factory=lambda: datetime.now().isoformat(timespec="seconds"))

    @property
    def tags(self) -> set[str]:
        return {tag.lower() for tag in TAG_RE.findall(self.text)}


class NotesShell(cmd.Cmd):
    intro = "notes shell. type help or ? to list commands, ctrl-d to quit."
    prompt = "(notes) "

    def __init__(self, path: Path = DEFAULT_FILE) -> None:
        super().__init__()
        self.path = path
        self.notes: dict[int, Note] = {}
        self._load()

    # --- storage ---------------------------------------------------------------
    def _load(self) -> None:
        if not self.path.exists():
            return
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
            self.notes = {n["id"]: Note(**n) for n in data["notes"]}
        except (ValueError, KeyError, TypeError) as exc:
            backup = self.path.with_suffix(".json.broken")
            self.path.replace(backup)
            print(f"warning: could not read {self.path} ({exc}); moved it to {backup}", file=sys.stderr)

    def _save(self) -> None:
        payload = {"notes": [asdict(n) for n in self.notes.values()]}
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")
        tmp.replace(self.path)

    # --- helpers ---------------------------------------------------------------
    def _all_tags(self) -> Counter[str]:
        return Counter(tag for note in self.notes.values() for tag in note.tags)

    @staticmethod
    def _show(note: Note) -> None:
        print(f"{note.id:>4}  {note.created[:10]}  {note.text}")

    # --- commands --------------------------------------------------------------
    def do_add(self, arg: str) -> None:
        """add <text>   add a note; use #tags anywhere in the text"""
        text = arg.strip()
        if not text:
            print("usage: add <text>")
            return
        note = Note(max(self.notes, default=0) + 1, text)
        self.notes[note.id] = note
        self._save()
        print(f"added note {note.id}" + (f" with tags {', '.join(sorted(note.tags))}" if note.tags else ""))

    def do_list(self, arg: str) -> None:
        """list [#tag]   list all notes, or only those with the given tag"""
        tag = arg.strip().lstrip("#").lower()
        notes = [n for n in self.notes.values() if not tag or tag in n.tags]
        if not notes:
            print("no notes" + (f" tagged #{tag}" if tag else ""))
        for note in notes:
            self._show(note)

    def do_find(self, arg: str) -> None:
        """find <word> | find #tag   case-insensitive search in the text, or by tag"""
        query = arg.strip().lower()
        if not query:
            print("usage: find <word> | find #tag")
            return
        if query.startswith("#"):
            hits = [n for n in self.notes.values() if query[1:] in n.tags]
        else:
            hits = [n for n in self.notes.values() if query in n.text.lower()]
        for note in hits:
            self._show(note)
        print(f"{len(hits)} match(es)")

    def complete_find(self, text: str, line: str, begidx: int, endidx: int) -> list[str]:
        # readline treats '#' as a word separator, so `text` is the part after '#'
        if line[begidx - 1:begidx] == "#":
            return [t for t in sorted(self._all_tags()) if t.startswith(text.lower())]
        return []

    def do_tags(self, arg: str) -> None:
        """tags   list all tags with how many notes use them"""
        counts = self._all_tags()
        if not counts:
            print("no tags yet")
        for tag, n in counts.most_common():
            print(f"  #{tag:<20} {n}")

    def do_del(self, arg: str) -> None:
        """del <id>   delete a note (asks for confirmation)"""
        try:
            note = self.notes[int(arg)]
        except (ValueError, KeyError):
            print(f"no note with id {arg.strip()!r}")
            return
        answer = input(f"delete note {note.id}: {note.text[:60]!r}? [y/N] ").strip().lower()
        if answer in ("y", "yes"):
            del self.notes[note.id]
            self._save()
            print("deleted")
        else:
            print("kept")

    def do_quit(self, arg: str) -> bool:
        """quit   leave the shell (ctrl-d works too)"""
        return True

    def do_EOF(self, arg: str) -> bool:
        print()  # newline after ^D so the shell prompt starts on a fresh line
        return True

    # --- cmd behaviour -------------------------------------------------------
    def emptyline(self) -> bool:
        # default: repeat the last command, which is dangerous right after `del 3`
        return False

    def default(self, line: str) -> None:
        print(f"unknown command: {line.split()[0]!r} (type help)")


if __name__ == "__main__":
    try:
        NotesShell().cmdloop()
    except KeyboardInterrupt:
        print()
